<?php $page_title='Track your order';require __DIR__.'/../partials/shop_open.php'; ?>
<main id="main" class="inner-page shell"><a class="text-link back-link" href="<?= url('?route=orders') ?>">← My orders</a><div class="page-intro"><p class="eyebrow">YOUR ORDER, AT A GLANCE</p><h1><?= $escape(ucfirst($order['status'])) ?>.</h1><p>Tracking number: <strong><?= $escape($order['tracking_number']) ?></strong></p></div><div class="contact-layout"><section class="shop-panel"><p class="eyebrow">YOUR PICKS</p><h2>Worth the wait.</h2><?php foreach($order['items'] as $item): ?><div class="order-total"><span><?= (int)$item['quantity'] ?> × <?= $escape($item['product_name']) ?></span><strong><?= $escape($currency) ?><?= number_format($item['line_total'],2) ?></strong></div><?php endforeach; ?><div class="order-total grand-total"><span>Total</span><strong><?= $escape($currency) ?><?= number_format($order['total'],2) ?></strong></div><p class="body-copy">Payment: <strong><?= $escape(ucfirst($order['payment_status'])) ?></strong></p><p class="body-copy">Pickup at <strong><?= $escape($order['branch_name']) ?></strong><br><?= $escape($order['branch_address'] ?? '') ?></p><?php if($order['payment_status']==='unpaid'&&$order['status']!=='cancelled'): ?><p class="body-copy">Pay when you collect your order. Show your tracking number to the staff.</p><?php endif; ?><a class="text-link" href="<?= url('?route=order_tracking&tracking='.rawurlencode($order['tracking_number'])) ?>">Refresh status ↻</a></section><section class="shop-panel"><p class="eyebrow">FOLLOW THE GOOD STUFF</p><h2>Order progress.</h2><ol class="order-timeline"><?php foreach($order['events'] as $event): ?><li><strong><?= $escape(ucfirst($event['status'])) ?></strong><p><?= $escape($event['status']==='pending'?'Your order has been received.':$event['note']) ?></p><time><?= $escape($event['created_at']) ?></time></li><?php endforeach; ?></ol></section></div></main>
